"""Assemble une sonde Node sur le DOM factice de tests/test_textes_js.py et l'execute."""
import os
import subprocess
import sys

DEPOT = sys.argv[1] if len(sys.argv) > 1 else "/opt/data/cache/scratch/rv3/base"
sys.path.insert(0, DEPOT)
from tests import test_textes_js as tj  # noqa: E402
from tests import test_quoi_js as tq  # noqa: E402

INTERFACE = tj.INTERFACE

PARCOURS = r"""
(async () => {
  const $h = s => document.querySelector(s);
  const dq = $h("#d-tx-quoi");
  const Q = s => dq.querySelector(s);
  const texte = el => el.textContent;
  const plat_texte = t => String(t).replace(/\s+/g, " ").trim();
  let HAPERCUS = [], HE = null, HGARDE = null, HREPONSE = null, HETATMODE = "immediat";
  let HSHOW = 0, HDEJA = 0, HETATCALLS = 0;
  const API = {
    ocr_etat: async () => { HETATCALLS++; if (HETATMODE === "porte" && HGARDE) await new Promise(r => HGARDE.push(r)); return HE; },
    ocr_documents: async () => ({ documents: [], total: 0, pages: 0 }),
    ocr_apercu: async (...a) => { HAPERCUS.push(a); if (HGARDE) await new Promise(r => HGARDE.push(r)); return HREPONSE; },
    ocr_lancer: async (...a) => { HLANCES.push(a); return { file: {} }; },
  };
  window.pywebview = { api: API };
  const vraiShow = dq.showModal.bind(dq);
  dq.showModal = function () { HSHOW++; if (dq.open) HDEJA++; vraiShow(); };
  const ferme = async () => { dq.querySelector("[data-ferme]").dispatchEvent({ type: "click" }); await Hattendre(10); };
  const clicEssai = async () => { Q(".tx-quoi-essai").dispatchEvent({ type: "click" }); await Hattendre(25); };
  const COMPTEURS = { documents: 3, pages: 9, a_verifier: 1, a_preparer: 2, pages_a_preparer: 5, octets_texte: 6710886, orphelins: 0 };
  const MOTEUR = { present: true, version: "5.5.3", source: "registre", exe: "x", langues: ["fra"], langues_effectives: "fra", repli: false, message: "" };
  const ETAT = { moteur: MOTEUR, active: true, mode_pdf: "aucun", occupe: false, compteurs: COMPTEURS };
  const BASE = { image: "data:image/png;base64,AAAA", largeur: 900, hauteur: 600, texte: "Un texte", confiance: 0.92,
                 qualite: "bon", source: "ocr", chemin: "Cours A/S1/a.pdf", nom: "a.pdf", page: 2, exemple: false };
  const ouvre = async etat => { TX = etat; HE = etat; $h("#tx-quoi").dispatchEvent({ type: "click" }); await Hattendre(25); };
  const dire = (nom, valeur) => console.log(nom + " : " + valeur);

  /* A. nom contenant un motif de remplacement et page 3 */
  await ouvre(ETAT); HREPONSE = Object.assign({}, BASE, { nom: "$& $1 $' a.pdf", page: 3 });
  await clicEssai();
  dire("A alt avec $& et page 3", JSON.stringify(Q(".tx-quoi-image").getAttribute("alt")));
  await ferme();

  /* B. reponse sans qualite */
  await ouvre(ETAT); HREPONSE = Object.assign({}, BASE, { qualite: undefined });
  await clicEssai();
  const confB = Q(".tx-quoi-confiance");
  dire("B sans qualite : ligne", JSON.stringify(plat_texte(texte(confB))));
  dire("B sans qualite : badge", confB.querySelector(".badge-qualite") ? JSON.stringify(texte(confB.querySelector(".badge-qualite"))) + " / " + confB.querySelector(".badge-qualite").className : "aucun badge");
  await ferme();

  /* C. confiance 0, 1, 1.5, -0.3 */
  await ouvre(ETAT);
  for (const [v, nom] of [[0, "0"], [1, "1"], [1.5, "1,5"], [-0.3, "-0,3"]]) {
    HREPONSE = Object.assign({}, BASE, { confiance: v });
    await clicEssai();
    dire("C confiance " + nom, JSON.stringify(plat_texte(texte(Q(".tx-quoi-confiance")))) + " visible=" + (Q(".tx-quoi-confiance").hidden === false));
  }
  await ferme();

  /* D. page absente */
  await ouvre(ETAT); HREPONSE = Object.assign({}, BASE, { page: undefined });
  await clicEssai();
  dire("D page absente : alt", JSON.stringify(Q(".tx-quoi-image").getAttribute("alt")));
  dire("D page absente : apercu visible", Q(".tx-quoi-apercu").hidden === false);
  await ferme();

  /* E. reponse null */
  await ouvre(ETAT); HREPONSE = null;
  const nToasts = $h("#toasts").children.length;
  await clicEssai();
  dire("E reponse null : toasts nouveaux", $h("#toasts").children.length - nToasts);
  dire("E reponse null : apercu visible", Q(".tx-quoi-apercu").hidden === false);
  dire("E reponse null : bouton actif", Q(".tx-quoi-essai").disabled === false);
  dire("E reponse null : libelle", JSON.stringify(texte(Q(".tx-quoi-essai"))));
  await ferme();

  /* F. deux ouvertures successives tres rapprochees, TX inconnu (ocr_etat retenu) */
  TX = null; HE = ETAT; HETATMODE = "porte"; HGARDE = []; HETATCALLS = 0; HSHOW = 0; HDEJA = 0;
  $h("#tx-quoi").dispatchEvent({ type: "click" });
  $h("#tx-quoi").dispatchEvent({ type: "click" });
  await Hattendre(20);
  HGARDE.splice(0).forEach(f => f()); HGARDE = null; HETATMODE = "immediat";
  await Hattendre(40);
  dire("F double ouverture : appels ocr_etat", HETATCALLS);
  dire("F double ouverture : showModal", HSHOW + " dont " + HDEJA + " sur un dialogue deja ouvert");
  dire("F double ouverture : panneau ouvert", dq.open === true);
  dire("F double ouverture : focus", Hactif === Q(".tx-quoi-essai"));
  await ferme();

  /* G. fermeture au milieu d'une lecture puis nouvel essai */
  await ouvre(ETAT); HGARDE = []; HREPONSE = Object.assign({}, BASE, { texte: "Premiere reponse" });
  const n0 = HAPERCUS.length;
  Q(".tx-quoi-essai").dispatchEvent({ type: "click" });
  await Hattendre(15);
  await ferme();                                    // ferme pendant la lecture
  dire("G fermeture pendant la lecture : bouton actif", Q(".tx-quoi-essai").disabled === false);
  await ouvre(ETAT);
  HREPONSE = Object.assign({}, BASE, { texte: "Seconde reponse" });
  Q(".tx-quoi-essai").dispatchEvent({ type: "click" });
  await Hattendre(15);
  dire("G nouvel essai : appels ocr_apercu", HAPERCUS.length - n0);
  const portes = HGARDE.splice(0); HGARDE = null;
  portes.forEach(f => f());
  await Hattendre(40);
  dire("G apres relachement : texte affiche", JSON.stringify(Q(".tx-quoi-texte").textContent));
  dire("G apres relachement : apercu visible", Q(".tx-quoi-apercu").hidden === false);
  dire("G apres relachement : bouton actif", Q(".tx-quoi-essai").disabled === false);
  dire("G ocr_lancer sur toute la sonde", HLANCES.length);
  console.log("FIN");
  process.exit(0);
})().catch(e => { console.error(e && e.stack ? e.stack : e); process.exit(1); });
"""

coupe = tj.ENTETE.find("/* ---- arbre de la page")
script = os.path.join("/opt/data/cache/scratch/rv3", "_probe_dom.js")
with open(script, "w", encoding="utf-8") as f:
    f.write(tj.ENTETE[:coupe] + "\n" + tq.OUTILS + "\n")
