    f.write("\n" + PARCOURS)
r = subprocess.run(["node", script, INTERFACE], capture_output=True, text=True, timeout=180)
print(r.stdout)
if r.returncode != 0:
    print("ECHEC", r.returncode)
    print(r.stderr[-3000:])

